import java.sql.*;
import java.util.*;
import java.util.regex.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.net.URLDecoder;

/**
 * Custom JDBC driver wrapper that supports expression-based connection routing
 * behind a reverse proxy. The proxy forwards X-Route-Expression headers
 * to allow dynamic datasource selection based on tenant context.
 */
public class RoutingDriverServlet extends HttpServlet {

    private static final Map<String, DataSourceConfig> TENANT_POOLS = new HashMap<>();
    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z][a-zA-Z0-9_]{0,63}$");
    private static final Set<String> ALLOWED_FUNCTIONS = new HashSet<>(Arrays.asList(
        "concat", "substring", "length", "upper", "lower", "trim"
    ));

    static {
        TENANT_POOLS.put("tenant_a", new DataSourceConfig("jdbc:postgresql://db1:5432/app", "app_user"));
        TENANT_POOLS.put("tenant_b", new DataSourceConfig("jdbc:postgresql://db2:5432/app", "app_user"));
        TENANT_POOLS.put("default", new DataSourceConfig("jdbc:postgresql://db0:5432/app", "app_user"));
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String routeExpr = req.getHeader("X-Route-Expression");
        String queryBody = req.getParameter("q");

        if (queryBody == null || queryBody.isEmpty()) {
            resp.sendError(400, "Missing query parameter");
            return;
        }

        // Validate query doesn't contain dangerous SQL
        if (!validateQuery(queryBody)) {
            resp.sendError(400, "Invalid query");
            return;
        }

        String tenantKey = resolveTenantFromExpression(routeExpr, req);
        DataSourceConfig config = TENANT_POOLS.getOrDefault(tenantKey, TENANT_POOLS.get("default"));

        try {
            String result = executeWithConfig(config, queryBody);
            resp.setContentType("application/json");
            resp.getWriter().write(result);
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    /**
     * Resolves tenant key from the routing expression header.
     * Expression format: ${property.path} or ${fn:function(arg)}
     * The reverse proxy is trusted to sanitize these headers.
     */
    private String resolveTenantFromExpression(String expr, HttpServletRequest req) {
        if (expr == null || expr.isEmpty()) {
            return "default";
        }

        // Decode the expression (proxy may URL-encode it)
        try {
            expr = URLDecoder.decode(expr, "UTF-8");
        } catch (Exception e) {
            return "default";
        }

        // Extract expression content from ${...} wrapper
        String resolved = evaluateExpression(expr, req);

        if (resolved != null && SAFE_IDENTIFIER.matcher(resolved).matches()) {
            return resolved;
        }
        return "default";
    }

    /**
     * Evaluates a simple expression language for routing.
     * Supports: ${header.X-Tenant-Id}, ${param.tenant}, ${fn:concat(a,b)}
     */
    private String evaluateExpression(String expr, HttpServletRequest req) {
        if (!expr.startsWith("${") || !expr.endsWith("}")) {
            return expr;
        }

        String inner = expr.substring(2, expr.length() - 1).trim();

        if (inner.startsWith("header.")) {
            String headerName = inner.substring(7);
            return req.getHeader(headerName);
        } else if (inner.startsWith("param.")) {
            String paramName = inner.substring(6);
            return req.getParameter(paramName);
        } else if (inner.startsWith("fn:")) {
            return evaluateFunction(inner.substring(3), req);
        } else if (inner.startsWith("ctx:")) {
            return evaluateContext(inner.substring(4), req);
        }
        return null;
    }

    /**
     * Evaluates context expressions for advanced routing.
     * Format: ctx:lookup(source, key) - looks up key in source
     */
    private String evaluateContext(String ctxExpr, HttpServletRequest req) {
        if (ctxExpr.startsWith("lookup(") && ctxExpr.endsWith(")")) {
            String args = ctxExpr.substring(7, ctxExpr.length() - 1);
            String[] parts = args.split(",", 2);
            if (parts.length == 2) {
                String source = parts[0].trim();
                String key = parts[1].trim();

                // Validate key against allowlist pattern
                if (!SAFE_IDENTIFIER.matcher(key).matches()) {
                    return null;
                }

                // Resolve the source from static mappings only
                if ("headers".equals(source)) {
                    return req.getHeader(key);
                } else if ("params".equals(source)) {
                    return req.getParameter(key);
                } else if ("tenants".equals(source)) {
                    // Only allow lookup in the tenant pool keys
                    return TENANT_POOLS.containsKey(key) ? key : null;
                }
            }
        }
        return null;
    }

    private String evaluateFunction(String fnExpr, HttpServletRequest req) {
        int parenIdx = fnExpr.indexOf('(');
        if (parenIdx < 0 || !fnExpr.endsWith(")")) return null;

        String fnName = fnExpr.substring(0, parenIdx);
        if (!ALLOWED_FUNCTIONS.contains(fnName)) return null;

        String argStr = fnExpr.substring(parenIdx + 1, fnExpr.length() - 1);
        String[] args = argStr.split(",");

        switch (fnName) {
            case "concat":
                StringBuilder sb = new StringBuilder();
                for (String arg : args) sb.append(resolveArg(arg.trim(), req));
                return sb.toString();
            case "lower":
                if (args.length > 0) return resolveArg(args[0].trim(), req).toLowerCase();
                break;
            case "upper":
                if (args.length > 0) return resolveArg(args[0].trim(), req).toUpperCase();
                break;
        }
        return null;
    }

    private String resolveArg(String arg, HttpServletRequest req) {
        if (arg.startsWith("'") && arg.endsWith("'")) {
            return arg.substring(1, arg.length() - 1);
        }
        if (arg.startsWith("header.")) return req.getHeader(arg.substring(7));
        if (arg.startsWith("param.")) return req.getParameter(arg.substring(6));
        return arg;
    }

    private boolean validateQuery(String query) {
        if (query == null) {
            return false;
        }
        String trimmed = query.trim();

        // Reject SQL comment sequences that can be used to smuggle statements.
        if (trimmed.contains("--") || trimmed.contains("/*") || trimmed.contains("*/") || trimmed.contains("#")) {
            return false;
        }

        // Disallow statement stacking. Allow a single optional trailing semicolon only.
        String noTrailingSemicolon = trimmed.endsWith(";")
                ? trimmed.substring(0, trimmed.length() - 1).trim()
                : trimmed;
        if (noTrailingSemicolon.contains(";")) {
            return false;
        }

        // Enforce a strict allowlist: only read-only SELECT statements are permitted.
        String upper = noTrailingSemicolon.toUpperCase(Locale.ROOT);
        if (!upper.startsWith("SELECT ") && !upper.startsWith("SELECT\t") && !upper.startsWith("SELECT\n")) {
            return false;
        }

        // Block dangerous operations even inside a SELECT (e.g. writable CTEs / functions).
        if (upper.contains("DROP ") || upper.contains("DELETE ") ||
            upper.contains("INSERT ") || upper.contains("UPDATE ") ||
            upper.contains("ALTER ") || upper.contains("TRUNCATE ") ||
            upper.contains("CREATE ") || upper.contains("GRANT ") ||
            upper.contains("REVOKE ") || upper.contains("MERGE ") ||
            upper.contains("CALL ") || upper.contains("EXEC") ||
            upper.contains("INTO ")) {
            return false;
        }
        return true;
    }

    private String executeWithConfig(DataSourceConfig config, String query) throws SQLException {
        // In production, this uses connection pooling
        try (Connection conn = DriverManager.getConnection(config.url, config.user, config.password)) {
            conn.setReadOnly(true);
            try (PreparedStatement stmt = conn.prepareStatement(query)) {
                ResultSet rs = stmt.executeQuery();
                return resultSetToJson(rs);
            }
        }
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        StringBuilder json = new StringBuilder("[");
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        boolean first = true;
        while (rs.next()) {
            if (!first) json.append(",");
            json.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) json.append(",");
                json.append("\"").append(escapeJson(meta.getColumnName(i))).append("\":");
                String value = rs.getString(i);
                if (value == null) {
                    json.append("null");
                } else {
                    json.append("\"").append(escapeJson(value)).append("\"");
                }
            }
            json.append("}");
            first = false;
        }
        json.append("]");
        return json.toString();
    }

    /**
     * Escapes a string for safe inclusion inside a JSON string literal.
     */
    private String escapeJson(String input) {
        if (input == null) {
            return "";
        }
        StringBuilder out = new StringBuilder(input.length() + 16);
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            switch (c) {
                case '\"': out.append("\\\""); break;
                case '\\': out.append("\\\\"); break;
                case '\b': out.append("\\b"); break;
                case '\f': out.append("\\f"); break;
                case '\n': out.append("\\n"); break;
                case '\r': out.append("\\r"); break;
                case '\t': out.append("\\t"); break;
                default:
                    if (c < 0x20) {
                        out.append(String.format("\\u%04x", (int) c));
                    } else {
                        out.append(c);
                    }
            }
        }
        return out.toString();
    }
}

class DataSourceConfig {
    String url;
    String user;
    String password;

    DataSourceConfig(String url, String user) {
        this.url = url;
        this.user = user;
        this.password = System.getenv("DB_PASSWORD");
    }
}
